/**
 * Simplified Chinese (zh-CN) dictionary for apps/app-web.
 *
 * Derived from `zh.ts` (Traditional, Taiwan-standard) via OpenCC tw2sp
 * (Taiwan-with-phrases to Simplified) plus a Mainland vocabulary pass
 * (封存→归档, 网域→域名, 帐→账, corner quotes to curly quotes, and the
 * like). When adding a key to `en.ts`, mirror it here in the same commit
 * in Mainland-standard Simplified Chinese; keep terminology consistent
 * with the existing keys in this file (登录 not 登入, 文件 not 档案,
 * 默认 not 预设). No em dashes in copy.
 */
